import csv
import io

from shelf import books, export


def setup_function():
    books.clear()


def rows(text):
    return list(csv.DictReader(io.StringIO(text)))


def test_dump_whole_catalogue():
    books.add("Dune", "Frank Herbert")
    books.add("Emma", "Jane Austen")
    assert export.dump() == "title,author\nDune,Frank Herbert\nEmma,Jane Austen\n"


def test_dump_quotes_commas_in_titles():
    books.add("Eats, Shoots & Leaves", "Lynne Truss")
    assert rows(export.dump()) == [{"title": "Eats, Shoots & Leaves", "author": "Lynne Truss"}]


def test_dump_empty_shelf():
    assert export.dump() == "title,author\n"


def test_dump_by_author():
    books.add("Dune", "Frank Herbert")
    books.add("Emma", "Jane Austen")
    books.add("Dune Messiah", "Frank Herbert")
    assert [r["title"] for r in rows(export.dump(author="Frank Herbert"))] == ["Dune", "Dune Messiah"]


def test_dump_by_unknown_author():
    books.add("Dune", "Frank Herbert")
    assert export.dump(author="Nobody") == "title,author\n"

